/* Core Energy: continuous birth, outward travel, fade, and invisible recycling. */
(() => {
  'use strict';
  const ART = 'data:image/png;base64,';
  const PACKED = '';
  const PARTICLES = Uint8Array.from(atob(PACKED),c=>c.charCodeAt(0));
  const COUNT = PARTICLES.byteLength / 16;
  const VERTEX = `#version 300 es
  precision highp float;
  in vec3 a_position;
  in vec4 a_color;
  uniform vec2 u_resolution;
  uniform float u_time;
  uniform float u_activity;
  uniform float u_motion;
  uniform float u_pass;
  out vec3 v_color;
  out float v_weight;
  out float v_opacity;
  out vec4 v_state;
  const float TAU=6.28318530718;
  float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
  float noise(vec2 p){
    vec2 a=floor(p),b=fract(p);b=b*b*(3.-2.*b);
    return mix(mix(hash(a),hash(a+vec2(1,0)),b.x),mix(hash(a+vec2(0,1)),hash(a+1.),b.x),b.y);
  }
  void main(){
    vec3 rest=a_position;
    float t=TAU*u_time/12.;
    float baseR=length(rest);
    vec3 direction=rest/max(baseR,.000001);
    float sector=noise(direction.xy*2.73+vec2(13.2,7.1));
    float sector2=noise(direction.xy*4.11+vec2(2.7,19.3));
    // No stationary nucleus or radius-cutout: even the innermost light flows.
    bool innerFlow=(gl_VertexID%6)==0;
    vec3 p;
    vec3 tint=a_color.rgb;
    float opacity;
    float age=0.;
    if(innerFlow){
      // A continuously replenished volume of light bridges the source and waves.
      // Its directions are independent of the oval silhouette in the artwork.
      float id=float(gl_VertexID);
      float seed=hash(vec2(id,17.3));
      float seed2=hash(vec2(id,51.9));
      float seed3=hash(vec2(id,103.7));
      age=fract(u_time/6.+seed);
      float az=TAU*seed2;
      float z=(seed3-.5)*1.7;
      float xy=sqrt(1.-z*z);
      float twist=.38*sin(az*2.1+t)+.24*sin(az*3.7-t*2.);
      az+=twist*(.25+.75*age)*u_motion;
      float reach=.28+.16*hash(vec2(id,87.1));
      float radius=.001+(reach-.001)*age;
      p=vec3(cos(az)*xy,sin(az)*xy,z)*radius;
      float birth=smoothstep(0.,.012,age);
      float fade=1.-smoothstep(.04,1.,age);
      opacity=birth*fade*fade*(.15+.48*seed3);
      tint=vec3(.08+.14*seed3,.36+.25*seed3,.92);
    }else{
      // Smooth, irregular launch phases keep adjacent traces connected without
      // rectangular fragments, mirrored lobes, or synchronized ring resets.
      float offset=baseR*3.8+noise(rest.xy*4.8+vec2(3.1,7.4))*.3;
      float clock=u_time/6.+offset;
      age=fract(clock);
      float generation=mod(floor(clock),2.);
      float reach=.60+.095*sector+.025*generation*sector2;
      // Radius strictly increases throughout every lifetime. No sine displacement.
      float radius=.001+(reach-.001)*age;
      float bend=(sector-.5)*.34+(sector2-.5)*.16*generation;
      float a=bend*u_motion*age*age;
      vec2 curved=mat2(cos(a),-sin(a),sin(a),cos(a))*direction.xy;
      p=vec3(curved,direction.z)*radius;
      float birth=smoothstep(0.,.018,age);
      float spread=smoothstep(.0,.065,age);
      float fade=1.-smoothstep(.40,1.,age);
      // Compensate for point crowding close to the emitter.
      float densityR=.001+(reach-.001)*min(age,.4);
      float density=min(1.,.018+densityR*densityR/max(baseR*baseR,.001));
      opacity=birth*spread*fade*fade*density;
      // Invisible at both age=0 and age=1; recycled geometry never teleports visibly.
    }
    v_opacity=opacity;
    v_state=vec4(age,length(p),opacity,innerFlow?1.:0.);
    float viewScale=min(u_resolution.x/2.0,u_resolution.y/1.50);
    vec2 screen=vec2(p.x,p.y-.010)*viewScale;
    gl_Position=vec4(screen/(u_resolution*.5),0.,1.);
    float pixelScale=viewScale/1024.;
    float desired=mix(innerFlow?2.25:1.80,innerFlow?8.0:5.1,u_pass)*pixelScale;
    gl_PointSize=max(1.0,desired);
    v_weight=min(1.,desired*desired);
    v_color=tint*(1.+u_activity*.18);
  }`;
  const FRAGMENT = `#version 300 es
  precision highp float;
  in vec3 v_color;
  in float v_weight;
  in float v_opacity;
  uniform float u_intensity;
  uniform float u_pass;
  out vec4 color;
  void main(){
    vec2 p=(gl_PointCoord-.5)*2.;
    float d=dot(p,p);
    if(d>1.)discard;
    float falloff=exp(-d*2.5);
    float gain=mix(1.48,.045,u_pass)*u_intensity;
    color=vec4(v_color*falloff*gain*v_weight*v_opacity,1.);
  }`;

  const clamp=(value,low,high,fallback)=>{
    const n=Number(value); return Number.isFinite(n)?Math.max(low,Math.min(high,n)):fallback;
  };

  class PortfolioEnergyCore extends HTMLElement {
    static get observedAttributes(){return ['paused','speed','intensity','activity','motion'];}
    constructor(){
      super();
      this.attachShadow({mode:'open'});
      this.shadowRoot.innerHTML=`<style>
        :host{display:block;position:relative;aspect-ratio:3/2;overflow:hidden;background:#000}
        canvas,img{display:block;width:100%;height:100%;object-fit:contain}
        canvas{position:absolute;inset:0}
        img{position:absolute;inset:0}
        [hidden]{display:none!important}
      </style><img alt="Blue holographic energy core"/><canvas aria-hidden="true"></canvas>`;
      this._canvas=this.shadowRoot.querySelector('canvas');
      this._canvas.hidden=true;
      this._poster=this.shadowRoot.querySelector('img');
      this._poster.src=ART;
      this._image=new Image();
      this._image.src=ART;
      this._time=0; this._last=0; this._frame=0;
      this._visible=true;this._lost=false;this._activity=0;this._ready=false;
      this._tick=this._tick.bind(this);
      this._visibility=()=>this._schedule();
      this._reduced=matchMedia('(prefers-reduced-motion: reduce)');
      this._preference=()=>{if(this._reduced.matches)this.pause();};
      this._canvas.addEventListener('webglcontextlost',event=>{
        event.preventDefault();this._lost=true;this._poster.hidden=false;this._canvas.hidden=true;this._schedule();
      });
      this._canvas.addEventListener('webglcontextrestored',()=>{
        this._lost=false;this._init();this._resize();this._schedule();
      });
    }
    connectedCallback(){
      this._sizeObserver=new ResizeObserver(()=>this._resize());
      this._sizeObserver.observe(this);
      this._intersection=new IntersectionObserver(entries=>{
        this._visible=entries[0].isIntersecting;this._schedule();
      });
      this._intersection.observe(this);
      document.addEventListener('visibilitychange',this._visibility);
      this._reduced.addEventListener('change',this._preference);
      if(this._reduced.matches)this.pause();
      const start=()=>{if(this.isConnected){this._init();this._resize();this._schedule();}};
      if(this._image.complete&&this._image.naturalWidth)start();
      else this._image.onload=start;
    }
    disconnectedCallback(){
      cancelAnimationFrame(this._frame);this._frame=0;
      this._image.onload=null;
      this._sizeObserver?.disconnect();this._intersection?.disconnect();
      document.removeEventListener('visibilitychange',this._visibility);
      this._reduced.removeEventListener('change',this._preference);
      this._dispose();
    }
    attributeChangedCallback(name){
      if(name==='paused'){
        this._schedule();this.dispatchEvent(new Event('motionchange'));
      }else this._draw();
    }
    get paused(){return this.hasAttribute('paused');}
    get failed(){return !!this._failed;}
    pause(){this.setAttribute('paused','');}
    play(){this.removeAttribute('paused');}
    setActivity(value){this.setAttribute('activity',String(clamp(value,0,1,0)));}
    get speed(){return clamp(this.getAttribute('speed')??1,.1,2.5,1);}
    get intensity(){return clamp(this.getAttribute('intensity')??1,.3,1.8,1);}
    get motion(){return clamp(this.getAttribute('motion')??1,0,2,1);}
    get activity(){return clamp(this.getAttribute('activity')??0,0,1,0);}
    _dispose(){
      if(this._gl&&!this._lost){
        if(this._program)this._gl.deleteProgram(this._program);
        if(this._buffer)this._gl.deleteBuffer(this._buffer);
      }
      this._program=null;this._buffer=null;this._ready=false;
    }
    _init(){
      try{
        this._dispose();
        const gl=this._canvas.getContext('webgl2',{alpha:false,antialias:false,depth:false,stencil:false});
        if(!gl)throw new Error('WebGL 2 unavailable; showing the approved still image.');
        this._gl=gl;
        const compile=(type,source)=>{
          const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);
          if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)){
            const message=gl.getShaderInfoLog(s);gl.deleteShader(s);throw new Error(message);
          }
          return s;
        };
        const vs=compile(gl.VERTEX_SHADER,VERTEX),fs=compile(gl.FRAGMENT_SHADER,FRAGMENT);
        const program=gl.createProgram();this._program=program;
        gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);
        gl.deleteShader(vs);gl.deleteShader(fs);
        if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(program));
        gl.useProgram(program);
        this._buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,this._buffer);
        gl.bufferData(gl.ARRAY_BUFFER,PARTICLES,gl.STATIC_DRAW);
        const pos=gl.getAttribLocation(program,'a_position'),col=gl.getAttribLocation(program,'a_color');
        gl.enableVertexAttribArray(pos);gl.vertexAttribPointer(pos,3,gl.FLOAT,false,16,0);
        gl.enableVertexAttribArray(col);gl.vertexAttribPointer(col,4,gl.UNSIGNED_BYTE,true,16,12);
        this._uniforms=Object.fromEntries(['resolution','time','activity','intensity','motion','pass'].map(n=>[n,gl.getUniformLocation(program,'u_'+n)]));
        gl.enable(gl.BLEND);gl.blendFunc(gl.ONE,gl.ONE);gl.clearColor(0,0,0,1);
        this._ready=true;this._failed=false;this._poster.hidden=true;this._canvas.hidden=false;
        this.dispatchEvent(new Event('ready'));
      }catch(error){
        this._ready=false;this._failed=true;this._poster.hidden=false;this._canvas.hidden=true;
        this.dispatchEvent(new CustomEvent('rendererror',{detail:error.message}));
      }
    }
    _resize(){
      const {width,height}=this.getBoundingClientRect();
      const ratio=Math.min(devicePixelRatio||1,2,Math.sqrt(1900000/Math.max(width*height,1)));
      this._canvas.width=Math.max(1,Math.round(width*ratio));
      this._canvas.height=Math.max(1,Math.round(height*ratio));this._draw();
    }
    _draw(){
      if(!this._ready||this._lost||!this.isConnected)return;
      const gl=this._gl,u=this._uniforms;
      gl.viewport(0,0,this._canvas.width,this._canvas.height);gl.useProgram(this._program);
      gl.uniform2f(u.resolution,this._canvas.width,this._canvas.height);
      gl.uniform1f(u.time,this._time);gl.uniform1f(u.activity,this._activity);
      gl.uniform1f(u.intensity,this.intensity);gl.uniform1f(u.motion,this.motion);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.uniform1f(u.pass,1);gl.drawArrays(gl.POINTS,0,COUNT);
      gl.uniform1f(u.pass,0);gl.drawArrays(gl.POINTS,0,COUNT);
    }
    _schedule(){
      cancelAnimationFrame(this._frame);this._frame=0;this._last=0;
      if(this.isConnected&&this._ready&&!this._lost&&!this.paused&&this._visible&&!document.hidden)
        this._frame=requestAnimationFrame(this._tick);
    }
    _tick(now){
      this._frame=0;
      if(!this.isConnected||!this._ready||this._lost||this.paused||!this._visible||document.hidden)return;
      const dt=this._last?Math.min((now-this._last)/1000,.05):0;this._last=now;
      this._activity+=(this.activity-this._activity)*(1-Math.exp(-dt*5));
      this._time=(this._time+dt*this.speed*(1+this._activity*.35))%12;
      this._draw();this._frame=requestAnimationFrame(this._tick);
    }
  }
  if(!customElements.get('portfolio-energy-core'))customElements.define('portfolio-energy-core',PortfolioEnergyCore);
})();
